-- Hemycare API - Flyway V1
-- PostgreSQL 17 | Schema public
-- UUID v7 identifiers are generated by the application (no database DEFAULT).
-- This migration defines only tables, constraints, and indexes.
-- Structural locking (structure_locked), authorization, and validation of
-- value_type against submitted values are handled by the backend for now.

-- ============================================================
-- 1. USERS AND PROFILES
-- ============================================================

CREATE TABLE app_user (
                          id              UUID          PRIMARY KEY,
                          email           VARCHAR(254)  NOT NULL,
                          password_hash   VARCHAR(255)  NOT NULL,
                          role            VARCHAR(20)   NOT NULL DEFAULT 'USER',
                          enabled         BOOLEAN       NOT NULL DEFAULT FALSE,
                          created_at      TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
                          updated_at      TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,

                          CONSTRAINT ck_app_user_role CHECK (role IN ('USER', 'ADMIN')),
                          CONSTRAINT ck_app_user_email_lower CHECK (email = LOWER(email))
);

-- Enforce case-insensitive email uniqueness.
CREATE UNIQUE INDEX uq_app_user_email_lower ON app_user (LOWER(email));

CREATE TABLE profile (
                         user_id     UUID          PRIMARY KEY,
                         full_name   VARCHAR(150)  NOT NULL,
                         birth_date  DATE          NOT NULL,

                         CONSTRAINT fk_profile_user FOREIGN KEY (user_id)
                             REFERENCES app_user (id)
);

-- ============================================================
-- 2. EXAM CATALOG
-- ============================================================

CREATE TABLE exam_type (
                           id      UUID          PRIMARY KEY,
                           code    VARCHAR(50)   NOT NULL,
                           name    VARCHAR(150)  NOT NULL,
                           active  BOOLEAN       NOT NULL DEFAULT TRUE,

                           CONSTRAINT uq_exam_type_code UNIQUE (code)
);

CREATE TABLE exam_schema (
                             id                UUID          PRIMARY KEY,
                             exam_type_id      UUID          NOT NULL,
                             code              VARCHAR(50)   NOT NULL,
                             name              VARCHAR(150)  NOT NULL,
                             active            BOOLEAN       NOT NULL DEFAULT TRUE,
                             structure_locked  BOOLEAN       NOT NULL DEFAULT FALSE,

                             CONSTRAINT fk_exam_schema_type FOREIGN KEY (exam_type_id)
                                 REFERENCES exam_type (id),
                             CONSTRAINT uq_exam_schema_type_code UNIQUE (exam_type_id, code),
    -- Required as a target key for the junction table composite foreign key.
                             CONSTRAINT uq_exam_schema_id_type UNIQUE (id, exam_type_id)
);

CREATE TABLE exam_definition (
                                 id                UUID           PRIMARY KEY,
                                 exam_type_id      UUID           NOT NULL,
                                 code              VARCHAR(80)    NOT NULL,
                                 label             VARCHAR(150)   NOT NULL,
                                 unit              VARCHAR(30),
                                 active            BOOLEAN        NOT NULL DEFAULT TRUE,
                                 structure_locked  BOOLEAN        NOT NULL DEFAULT FALSE,
                                 value_type        VARCHAR(20)    NOT NULL,
                                 decimal_places    SMALLINT,
                                 min_value         NUMERIC(15,6),
                                 max_value         NUMERIC(15,6),
                                 max_length        INTEGER,

                                 CONSTRAINT fk_exam_definition_type FOREIGN KEY (exam_type_id)
                                     REFERENCES exam_type (id),
                                 CONSTRAINT uq_exam_definition_type_code UNIQUE (exam_type_id, code),
    -- Required as a target key for the junction table composite foreign key.
                                 CONSTRAINT uq_exam_definition_id_type UNIQUE (id, exam_type_id),
                                 CONSTRAINT ck_exam_definition_value_type
                                     CHECK (value_type IN ('INTEGER', 'DECIMAL', 'TEXT')),
                                 CONSTRAINT ck_exam_definition_decimal_places
                                     CHECK (decimal_places IS NULL OR decimal_places BETWEEN 0 AND 6),
                                 CONSTRAINT ck_exam_definition_value_range
                                     CHECK (min_value IS NULL OR max_value IS NULL OR min_value <= max_value),
                                 CONSTRAINT ck_exam_definition_max_length
                                     CHECK (max_length IS NULL OR max_length > 0),
    -- Each result type accepts only compatible metadata.
                                 CONSTRAINT ck_exam_definition_type_metadata CHECK (
                                     (value_type = 'INTEGER'
                                         AND decimal_places IS NULL
                                         AND max_length IS NULL
                                         AND (min_value IS NULL OR min_value = TRUNC(min_value))
                                         AND (max_value IS NULL OR max_value = TRUNC(max_value)))
                                         OR (value_type = 'DECIMAL'
                                         AND decimal_places IS NOT NULL
                                         AND max_length IS NULL)
                                         OR (value_type = 'TEXT'
                                         AND decimal_places IS NULL
                                         AND min_value IS NULL
                                         AND max_value IS NULL
                                         AND unit IS NULL)
                                     )
);

-- Defines each schema's fields, display order, and required flags.
CREATE TABLE exam_schema_definition (
                                        schema_id      UUID     NOT NULL,
                                        definition_id  UUID     NOT NULL,
                                        exam_type_id   UUID     NOT NULL,
                                        display_order  INTEGER  NOT NULL,
                                        required       BOOLEAN  NOT NULL DEFAULT TRUE,

                                        CONSTRAINT pk_exam_schema_definition
                                            PRIMARY KEY (schema_id, definition_id),
                                        CONSTRAINT uq_exam_schema_definition_order
                                            UNIQUE (schema_id, display_order),
                                        CONSTRAINT ck_exam_schema_definition_order
                                            CHECK (display_order > 0),
                                        CONSTRAINT fk_schema_definition_schema_type
                                            FOREIGN KEY (schema_id, exam_type_id)
                                                REFERENCES exam_schema (id, exam_type_id),
                                        CONSTRAINT fk_schema_definition_definition_type
                                            FOREIGN KEY (definition_id, exam_type_id)
                                                REFERENCES exam_definition (id, exam_type_id)
);

-- ============================================================
-- 3. USER EXAM RECORDS AND RESULTS
-- ============================================================

CREATE TABLE exam_record (
                             id          UUID         PRIMARY KEY,
                             user_id     UUID         NOT NULL,
                             schema_id   UUID         NOT NULL,
                             exam_date   DATE         NOT NULL,
                             created_at  TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
                             updated_at  TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,

                             CONSTRAINT fk_exam_record_user FOREIGN KEY (user_id)
                                 REFERENCES app_user (id),
                             CONSTRAINT fk_exam_record_schema FOREIGN KEY (schema_id)
                                 REFERENCES exam_schema (id),
    -- Required to ensure each result references its record's schema.
                             CONSTRAINT uq_exam_record_id_schema UNIQUE (id, schema_id)
);

CREATE TABLE exam_result (
                             id                    UUID           PRIMARY KEY,
                             exam_record_id        UUID           NOT NULL,
                             schema_id             UUID           NOT NULL,
                             result_definition_id  UUID           NOT NULL,
                             numeric_value         NUMERIC(15,6),
                             text_value            TEXT,

                             CONSTRAINT uq_exam_result_record_definition
                                 UNIQUE (exam_record_id, result_definition_id),
                             CONSTRAINT fk_exam_result_record_schema
                                 FOREIGN KEY (exam_record_id, schema_id)
                                     REFERENCES exam_record (id, schema_id),
                             CONSTRAINT fk_exam_schema_definition
                                 FOREIGN KEY (schema_id, result_definition_id)
                                     REFERENCES exam_schema_definition (schema_id, definition_id),
                             CONSTRAINT ck_exam_result_one_value
                                 CHECK ((numeric_value IS NOT NULL) <> (text_value IS NOT NULL)),
                             CONSTRAINT ck_exam_result_text_not_blank
                                 CHECK (text_value IS NULL OR LENGTH(BTRIM(text_value)) > 0)
);

-- ============================================================
-- 4. INDEXES FOR QUERIES AND RELATIONSHIPS
-- ============================================================

-- User history sorted by exam date, with a stable pagination tie-breaker.
CREATE INDEX idx_exam_record_user_date
    ON exam_record (user_id, exam_date DESC, id);

-- Records using a schema (including first-use checks).
CREATE INDEX idx_exam_record_schema
    ON exam_record (schema_id);

-- Results lookup by definition (charts and trends).
CREATE INDEX idx_exam_result_definition_id
    ON exam_result (result_definition_id);

-- Reverse junction-table lookups (definitions shared by multiple schemas).
CREATE INDEX idx_exam_schema_definition_definition_id
    ON exam_schema_definition (definition_id);

-- NOTES:
-- * PostgreSQL automatically creates indexes for primary keys and UNIQUE constraints.
-- * No triggers are created in V1.
-- * First-use schema/definition locking, allowed edits, value_type validation,
--   and completeness of required fields must be enforced by application
--   services until a later migration adds database-level enforcement.
-- * The database does not automatically update updated_at on UPDATE.
